package com.campus.registration.repository; import com.campus.registration.model.*;import java.sql.*; public class StudentRepository{final Database db;public StudentRepository(Database d){db=d;}public void save(Student x)throws SQLException{try(var c=db.connect();var p=c.prepareStatement("INSERT OR REPLACE INTO students VALUES(?,?,?,?)")){p.setString(1,x.id());p.setString(2,x.name());p.setString(3,x.program());p.setInt(4,x.semester());p.executeUpdate();}}}